package com.karic.penny;

import org.junit.Test;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.*;
import static org.junit.Assert.*;

/** Synthetic transaction IDs and account suffixes retain the supplied formats, not personal SMS. */
public class LedgerTest {
    static final long NOW=Instant.parse("2026-11-07T09:00:00Z").toEpochMilli();
    static Transaction sms(String sender,String body,long at){Transaction t=TransactionParser.parse(sender,body,at);assertNotNull(body,t);return t;}
    static Transaction bank(String amount,String date,String extra){return sms("Centenary","a trxn of "+amount+" on your A/C **123 on "+date+". "+extra,NOW);}
    static Transaction momo(String id,String balance,long received){return sms("MTN","MTN has deducted UGX 6500 at a fee of UGX 0. Transaction ID: "+id+". Message: Bundle Purchase. New balance is:UGX "+balance,received);}
    static Ledger ledger(Transaction... ts){return new Ledger(Arrays.asList(ts),Collections.emptyMap());}
    static void money(String expected,BigDecimal actual){assertNotNull(actual);assertEquals(0,new BigDecimal(expected).compareTo(actual));}
    static Ledger.Totals all(Ledger l){return l.totals(0,Long.MAX_VALUE,"All Accounts");}
    @Test public void centenarySignedDebitAndExplicitBalance(){Transaction t=bank("-10,000","06-11-2026 at 09:52","Bal:50,621");money("10000",t.amount);money("50621",t.reportedBalance);assertEquals("OUT",t.direction);assertEquals("*123",t.account);assertEquals(Instant.parse("2026-11-06T06:52:00Z").toEpochMilli(),t.timestamp);assertEquals("Reported",t.balanceType);assertNull(t.fee);}
    @Test public void centenaryPayerIsPreservedAndSalaryNotAssumed(){Transaction t=bank("1,680,250","06-11-2026 at 09:52","(EFT-ORDER EXAMPLE ADMINISTRATION/Head Office)");assertEquals("IN",t.direction);assertTrue(t.counterparty.contains("EXAMPLE ADMINISTRATION"));assertEquals("Income (unconfirmed)",t.category);money("1680250",all(ledger(t)).income);}
    @Test public void bundleDebitZeroFeeAndDescription(){Transaction t=momo("90000000001","4663",NOW);money("6500",t.amount);money("0",t.fee);money("4663",t.reportedBalance);assertEquals("MTN Data Bundle",t.description);assertEquals("Airtime & Data",t.category);}
    @Test public void duplicateConfirmationsCountOnceAndKeepPrecision(){Transaction a=momo("90000000001","4663",NOW),b=momo("90000000001","4663.36",NOW+1000);Ledger l=ledger(a,b);assertEquals(1,l.entries.size());money("6500",all(l).spending);money("4663.36",l.accounts.get("MTN:unknown").latest.value);assertEquals(2,l.entries.get(0).sources.size());}
    @Test public void precisionDoesNotDependOnImportOrder(){Ledger l=ledger(momo("90000000001","4663.36",NOW),momo("90000000001","4663",NOW+1000));money("4663.36",l.accounts.get("MTN:unknown").latest.value);}
    @Test public void repeatedImportsAreIdempotent(){Transaction a=momo("90000000001","4663",NOW);Ledger l=ledger(a,a,a);assertEquals(1,l.entries.size());assertEquals(1,l.entries.get(0).sources.size());money("6500",all(l).spending);}
    @Test public void noIdIdenticalImportIsIdempotent(){Transaction a=bank("-1000","06-11-2026 at 09:52","Bal:5000");Ledger l=ledger(a,a);assertEquals(1,l.entries.size());money("1000",all(l).spending);}
    @Test public void repeatedLegitimatePurchasesWithDifferentIdsRemainSeparate(){Ledger l=ledger(momo("90000000001","4663",NOW),momo("90000000002","1163",NOW));assertEquals(2,l.entries.size());money("13000",all(l).spending);}
    @Test public void noIdSeparateSmsAreFlaggedNotMerged(){Transaction a=sms("MTN","MTN has deducted UGX 6500. Message: Bundle Purchase",NOW),b=sms("MTN","MTN has deducted UGX 6500. Message: Bundle Purchase",NOW+1000);Ledger l=ledger(a,b);assertEquals(2,l.entries.size());assertTrue(l.entries.get(0).warnings.stream().anyMatch(w->w.startsWith("Possible duplicate")));}
    @Test public void approvalIsNotACompletedPayment(){Transaction a=sms("MTN","Dial *165# and select My Approvals to allow payment of UGX 6500",NOW);assertEquals(Transaction.Status.APPROVAL,a.status);money("0",all(ledger(a)).spending);assertNull(ledger(a).accounts.get("MTN:unknown").latest);Transaction b=sms("MTN","Dial *165# and select My Approvals to allow payment",NOW);assertNull(b.amount);assertNull(b.reportedBalance);assertEquals("Payment approval request",b.description);money("0",all(ledger(b)).spending);}
    @Test public void failedPaymentDoesNotCountOrReplaceBalance(){Transaction a=sms("MTN","MTN payment of UGX 6500 failed. New balance UGX 999999",NOW);Ledger l=ledger(a);money("0",all(l).spending);assertNull(l.accounts.get("MTN:unknown").latest);}
    @Test public void pendingCardKeepsAvailableBalanceWithoutSpending(){Transaction a=bank("-10000","06-11-2026 at 09:52","pending settlement. Available balance: UGX 50,621. Ref: CARD90001");Ledger l=ledger(a);assertEquals(Transaction.Status.PENDING,l.entries.get(0).status);money("0",all(l).spending);money("50621",l.accounts.get("Centenary Bank:*123").latest.value);assertEquals("Available",l.accounts.get("Centenary Bank:*123").latest.type);}
    @Test public void settlementSameIdCountsOnce(){Transaction p=bank("-10000","06-11-2026 at 09:52","pending settlement. Available balance: UGX 50621. Ref: CARD90001"),c=bank("-10000","07-11-2026 at 09:52","settled. Available balance: UGX 50621. Ref: CARD90001");Ledger l=ledger(c,p);assertEquals(1,l.entries.size());assertEquals(Transaction.Status.COMPLETED,l.entries.get(0).status);money("10000",all(l).spending);}
    @Test public void settlementNewIdLinksExplicitOriginal(){Transaction p=bank("-10000","06-11-2026 at 09:52","pending settlement. Ref: CARD90001"),c=bank("-10000","07-11-2026 at 09:52","settled. Ref: POST90001. Original transaction ID: CARD90001");Ledger l=ledger(c,p);assertEquals(1,l.entries.size());money("10000",all(l).spending);}
    @Test public void unlinkedSettlementIsFlaggedWithoutGuessing(){Transaction p=bank("-10000","06-11-2026 at 09:52","pending settlement. Ref: CARD90001"),c=bank("-10000","07-11-2026 at 09:52","settled. Ref: POST90001");Ledger l=ledger(c,p);assertEquals(2,l.entries.size());money("10000",all(l).spending);}
    @Test public void reversalLinksToOriginalWithoutBecomingIncome(){Transaction a=momo("90000000001","4663",NOW),r=sms("MTN","MTN reversed UGX 6500. Ref: REV90001. Original transaction ID: 90000000001. New balance UGX 11163",NOW+1000);Ledger l=ledger(r,a);assertEquals(1,l.entries.size());assertEquals(Transaction.Status.REVERSED,l.entries.get(0).status);money("0",all(l).income);money("0",all(l).spending);money("11163",l.accounts.get("MTN:unknown").latest.value);}
    @Test public void standaloneReversalIsNotInventedIncome(){Transaction r=sms("MTN","MTN reversed UGX 6500. Original transaction ID: 90000000001",NOW);Ledger l=ledger(r);money("0",all(l).income);assertTrue(l.entries.get(0).warnings.stream().anyMatch(w->w.contains("original not found")));}
    @Test public void transfersAreNotAssumedFromWording(){Transaction a=bank("-10000","06-11-2026 at 09:52","Funds Transfer (Mobile) / Ebanking. Fee UGX 50");Ledger l=ledger(a);assertFalse(l.entries.get(0).internal);money("10050",all(l).spending);}
    @Test public void manualInternalTransferExcludesPrincipalRetainsFee(){Transaction a=bank("-10000","06-11-2026 at 09:52","Funds Transfer (Mobile) / Ebanking. Fee UGX 50. Ref: BANK90001"),b=sms("MTN","MTN received UGX 10000 from Bank. Ref: MOMO90001. Fee UGX 0",NOW);Map<String,Ledger.Edit> edits=new HashMap<>();edits.put(Ledger.key(a),new Ledger.Edit(a.category,true,Ledger.key(b)));edits.put(Ledger.key(b),new Ledger.Edit(b.category,true,Ledger.key(a)));Ledger l=new Ledger(Arrays.asList(a,b),edits);money("0",all(l).income);money("50",all(l).spending);money("50",all(l).fees);}
    @Test public void sharedReferenceAndMatchingOppositeLegsAutoLink(){Transaction a=bank("-10000","06-11-2026 at 09:52","Funds Transfer. Fee UGX 50. Ref: SHARED90001"),b=sms("MTN","MTN received UGX 10000 from Bank on 06-11-2026 at 09:53. Ref: SHARED90001. Fee UGX 0",NOW);Ledger l=ledger(a,b);assertTrue(l.entries.stream().allMatch(e->e.internal));money("50",all(l).spending);money("0",all(l).income);}
    @Test public void matchingAmountAloneNeverAutoLinks(){Transaction a=bank("-10000","06-11-2026 at 09:52","Funds Transfer. Ref: BANK90001"),b=sms("MTN","MTN received UGX 10000 from Bank on 06-11-2026 at 09:53. Ref: MOMO90001",NOW);Ledger l=ledger(a,b);assertFalse(l.entries.stream().anyMatch(e->e.internal));money("10000",all(l).income);money("10000",all(l).spending);}
    @Test public void feeIsNotChargedTwice(){Transaction a=sms("MTN","MTN sent UGX 10000 to Example at a fee of UGX 500. New balance UGX 1000. Ref: MOMO90001",NOW);Ledger l=ledger(a);money("10000",all(l).principal);money("500",all(l).fees);money("10500",all(l).spending);}
    @Test public void unknownFieldsStayUnknown(){Transaction a=sms("MTN","MTN paid UGX 6500 to Example",NOW);assertNull(a.fee);assertNull(a.reportedBalance);assertNull(a.transactionId);assertEquals("unknown",a.account);assertEquals(1,all(ledger(a)).unknownFees);}
    @Test public void commasDecimalsRepeatedCurrencyAndNegativeSpaces(){Transaction a=sms("MTN","MTN has deducted UGX UGX 6,500.25 at a fee of UGX UGX 0.75. New balance is:UGX 4,663.36",NOW);money("6500.25",a.amount);money("0.75",a.fee);money("4663.36",a.reportedBalance);Transaction b=bank("- 10,000","06-11-2026 at 09:52","Bal:50,621");money("10000",b.amount);assertEquals("OUT",b.direction);}
    @Test public void referencesPhoneNumbersAndBalanceAreNotAmounts(){Transaction a=sms("MTN","Ref: 90000000001. MTN sent UGX 6500 to 0770000000. New balance UGX 4663",NOW);money("6500",a.amount);Transaction b=sms("MTN","Ref: 90000000001 MTN payment to 0770000000. New balance UGX 4663",NOW);assertNull(b.amount);money("0",all(ledger(b)).spending);}
    @Test public void otpIsNotRetained(){assertNull(TransactionParser.parse("MTN","Your OTP to confirm payment UGX 5000 is 123456",NOW));}
    @Test public void historicalImportsCannotOverwriteNewerBalances(){Transaction recent=bank("-1000","06-11-2026 at 09:52","Bal:50621"),older=bank("-2000","01-11-2026 at 09:52","Bal:999999");older.receivedAt=NOW+100000;for(List<Transaction> rows:Arrays.asList(Arrays.asList(recent,older),Arrays.asList(older,recent)))money("50621",new Ledger(rows,Collections.emptyMap()).accounts.get("Centenary Bank:*123").latest.value);}
    @Test public void explicitDateBeatsArrivalOrder(){Transaction newer=bank("-1000","06-11-2026 at 09:52","Bal:50621"),older=sms("Centenary","a trxn of -2000 on your A/C **123 on 01-11-2026 at 09:52. Bal:999999",NOW+86400000);money("50621",ledger(older,newer).accounts.get("Centenary Bank:*123").latest.value);}
    @Test public void historicalBalancesAreNotSummedOrDebitedAgain(){Ledger l=ledger(bank("-1000","01-11-2026 at 09:52","Bal:51621"),bank("-1000","06-11-2026 at 09:52","Bal:50621"));money("50621",l.accounts.get("Centenary Bank:*123").latest.value);money("2000",all(l).spending);}
    @Test public void missingBalanceIsNotZero(){Ledger l=ledger(sms("MTN","MTN paid UGX 6500 to Example",NOW));assertNull(l.accounts.get("MTN:unknown").latest);}
    @Test public void explicitZeroBalanceIsKnown(){Ledger l=ledger(momo("90000000001","0",NOW));money("0",l.accounts.get("MTN:unknown").latest.value);}
    @Test public void availableAndLedgerTypesRemainDistinct(){Transaction a=bank("-1000","01-11-2026 at 09:52","Available balance UGX 3000. Ref: CARD90001"),b=bank("-500","02-11-2026 at 09:52","Ledger balance UGX 4000. Ref: BANK90002");Ledger.Account account=ledger(a,b).accounts.get("Centenary Bank:*123");assertEquals(2,account.byType.size());assertEquals("Ledger",account.latest.type);}
    @Test public void conflictsDoNotFabricateTransactionsOrBalances(){Transaction a=momo("90000000001","4663",NOW),b=sms("MTN","MTN has deducted UGX 7000. Transaction ID: 90000000001. New balance UGX 4000",NOW+1000);Ledger l=ledger(a,b);assertTrue(l.entries.get(0).conflict);money("0",all(l).spending);assertNull(l.accounts.get("MTN:unknown").latest);}
    @Test public void mismatchedBalancesFlagRatherThanInventFees(){for(String fee:Arrays.asList("Fee UGX 0. ","")){Ledger l=ledger(bank("-1000","01-11-2026 at 09:52",fee+"Bal:5000"),bank("-1000","02-11-2026 at 09:52",fee+"Bal:3500"));money("0",all(l).fees);assertTrue(l.accounts.get("Centenary Bank:*123").warnings.stream().anyMatch(w->w.contains("No fee inferred")));if(fee.isEmpty())assertTrue(l.accounts.get("Centenary Bank:*123").warnings.stream().anyMatch(w->w.contains("Fee unknown")));}}
    @Test public void providerAccountAndIdAllScopeDeduplication(){Transaction a=bank("-1000","06-11-2026 at 09:52","Ref: SAME90001"),b=sms("Centenary","a trxn of -1000 on your A/C **456 on 06-11-2026 at 09:52. Ref: SAME90001",NOW);Ledger l=ledger(a,b);assertEquals(2,l.entries.size());money("2000",all(l).spending);}
    @Test public void filtersUseHalfOpenDateRangesAndAccountKinds(){Transaction a=momo("90000000001","4663",NOW),b=bank("-1000","06-11-2026 at 09:52","Bal:50621");Ledger l=ledger(a,b);money("0",l.totals(NOW,NOW+1,"Bank").spending);money("6500",l.totals(NOW,NOW+1,"Mobile Money").spending);money("0",l.totals(NOW-1,NOW,"All Accounts").spending);}
    @Test public void slashIsoAndTwoDigitYearsParseInEastAfrica(){for(String d:Arrays.asList("06/11/2026","2026-11-06","06/11/26","06 Nov 2026")){Transaction t=bank("-1000",d+" at 09:52:30","Bal:50621");assertEquals(d,Instant.parse("2026-11-06T06:52:30Z").toEpochMilli(),t.timestamp);}}
    @Test public void invalidDateUsesSmsTimeAndIsLabelled(){Transaction t=bank("-1000","31-02-2026 at 09:52","Bal:50621");assertEquals(NOW,t.timestamp);assertEquals("SMS received time",t.timeSource);assertTrue(t.warnings.stream().anyMatch(w->w.contains("Invalid date")));}
    @Test public void correctedCategoryPersistsWithoutChangingAmount(){Transaction a=momo("90000000001","4663",NOW);Ledger l=new Ledger(Arrays.asList(a),Collections.singletonMap(Ledger.key(a),new Ledger.Edit("Bills",false,null)));assertEquals("Bills",l.entries.get(0).category);money("6500",all(l).spending);}
    @Test public void entryAndBalanceResultsArePermutationInvariant(){Transaction a=bank("-1000","06-11-2026 at 09:52","Bal:50621"),b=momo("90000000001","4663",NOW),c=momo("90000000001","4663.36",NOW+1000);Ledger one=ledger(a,b,c),two=ledger(c,a,b);money(all(one).spending.toPlainString(),all(two).spending);assertEquals(one.entries.size(),two.entries.size());money(one.accounts.get("MTN:unknown").latest.value.toPlainString(),two.accounts.get("MTN:unknown").latest.value);}
    @Test public void oldAmbiguityDoesNotHideNewerValidBalance(){Transaction a=bank("-1000","01-11-2026 at 09:52","Bal:5000. Ref: BANK90001"),b=bank("-500","01-11-2026 at 09:52","Bal:4500. Ref: BANK90002"),c=bank("-200","06-11-2026 at 09:52","Bal:4300. Ref: BANK90003");money("4300",ledger(c,b,a).accounts.get("Centenary Bank:*123").latest.value);}
    @Test public void reversalFollowsSettlementToOriginalAuthorization(){Transaction p=bank("-10000","05-11-2026 at 09:52","pending settlement. Ref: CARD90001"),c=bank("-10000","06-11-2026 at 09:52","settled. Ref: POST90001. Original transaction ID: CARD90001"),r=bank("-10000","07-11-2026 at 09:52","reversed. Ref: REV90001. Original transaction ID: POST90001");Ledger l=ledger(r,c,p);assertEquals(1,l.entries.size());money("0",all(l).spending);assertEquals(Transaction.Status.REVERSED,l.entries.get(0).status);}
    @Test public void missingAccountOnOneConfirmationCanLinkByUniqueKnownId(){Transaction a=momo("90000000001","4663",NOW),b=sms("MTN","MTN has deducted UGX 6500 from your account 0770000000. Transaction ID: 90000000001. New balance UGX 4663.36",NOW+1000);Ledger l=ledger(a,b);assertEquals(1,l.entries.size());money("6500",all(l).spending);money("4663.36",l.accounts.get("MTN:0770000000").latest.value);}
    @Test public void ambiguousSharedReferenceDoesNotAutoLink(){Transaction a=bank("-10000","06-11-2026 at 09:52","Funds Transfer. Ref: SHARED90001"),b=sms("Centenary","a trxn of -10000 on your A/C **456 on 06-11-2026 at 09:52. Funds Transfer. Ref: SHARED90001",NOW),c=sms("MTN","MTN received UGX 10000 on 06-11-2026 at 09:53. Ref: SHARED90001",NOW);assertFalse(ledger(a,b,c).entries.stream().anyMatch(e->e.internal));}
    @Test public void receiverAndInboxUseSharedSmsTimestampForIdentity(){Transaction a=TransactionParser.parse("MTN","MTN paid UGX 6500",NOW+400,NOW),b=TransactionParser.parse("MTN","MTN paid UGX 6500",NOW+800,NOW);Ledger l=ledger(a,b);assertEquals(1,l.entries.size());money("6500",all(l).spending);}
    @Test public void bothAvailableAndLedgerBalancesInOneSmsAreRetained(){Transaction a=bank("-1000","06-11-2026 at 09:52","Available balance UGX 3000. Ledger balance UGX 4000");Ledger.Account account=ledger(a).accounts.get("Centenary Bank:*123");assertEquals(2,account.byType.size());money("3000",account.latest.value);assertEquals("Available",account.latest.type);}
    @Test public void negativeCompletionWordingNeverCounts(){for(String wording:Arrays.asList("was not successful","has not been completed","was not deducted")){Transaction t=sms("MTN","MTN payment of UGX 6500 "+wording,NOW);assertEquals(Transaction.Status.FAILED,t.status);money("0",all(ledger(t)).spending);}}
    @Test public void inconsistentSameTypeBalancesInOneSmsAreNotReliable(){Transaction a=bank("-1000","06-11-2026 at 09:52","Bal:3000. New balance UGX 4000");assertNull(ledger(a).accounts.get("Centenary Bank:*123").latest);}
    @Test public void balanceOnlyConfirmationRefinesKnownTransaction(){Transaction a=momo("90000000001","4663",NOW),b=sms("MTN","MTN confirmation. Transaction ID: 90000000001. New balance is:UGX 4663.36",NOW+1000);assertNull(b.amount);assertNull(b.direction);Ledger l=ledger(a,b);assertEquals(1,l.entries.size());money("6500",all(l).spending);money("4663.36",l.accounts.get("MTN:unknown").latest.value);}
    @Test public void explicitStandaloneBalanceDoesNotInventCashFlow(){Transaction t=sms("MTN","Your MTN available balance is UGX 4663.36",NOW);Ledger l=ledger(t);money("4663.36",l.accounts.get("MTN:unknown").latest.value);money("0",all(l).income);money("0",all(l).spending);assertNull(t.amount);assertEquals("Mobile money balance report",t.description);}
    @Test public void projectedBalanceIsNotAnAccountSnapshot(){Transaction t=sms("MTN","MTN estimated available balance is UGX 4663.36",NOW);assertNull(ledger(t).accounts.get("MTN:unknown").latest);}
}
